WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (ORDER BY age, id) row_seq, NTILE(5) OVER (ORDER BY credit_limit DESC, id) credit_limit_bucket FROM customers) SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, CASE WHEN credit_limit >= 16200 THEN 'LARGE' ELSE 'SMALL' END AS credit_limit_tier, segment, BIT_AND(age) AS age_bit_and, ROUND(SUM(credit_limit_bucket) / NULLIF(COUNT(CASE WHEN segment = 'Consumer' THEN 1 END), 0), 2) AS credit_limit_bucket_per_consumer, SIZE(COLLECT_SET(city)) AS num_cities, APPROX_PERCENTILE(credit_limit, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_quartiles, GROUPING_ID() AS grouping_level FROM with_windows GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', signup_date), CASE WHEN credit_limit >= 16200 THEN 'LARGE' ELSE 'SMALL' END, segment), (DATE_TRUNC('WEEK', signup_date), CASE WHEN credit_limit >= 16200 THEN 'LARGE' ELSE 'SMALL' END)) HAVING num_cities < 1000 ORDER BY credit_limit_bucket_per_consumer
